                    '            <input name="card_nome" value="{{ card.card_nome }}" placeholder="Ex: COOPEX '
                    'Entregas">\n'
                    '          </label>\n'
                    '\n'
                    '          <label>Descrição curta\n'
                    '            <input name="card_descricao" value="{{ card.card_descricao }}" placeholder="Ex: '
