                    '          </label>\n'
                    '\n'
                    '          <label class="full">Bio / apresentação\n'
                    '            <textarea name="card_bio" placeholder="Texto curto que aparece abaixo do nome">{{ '
                    'card.card_bio }}</textarea>\n'
                    '          </label>\n'
                    '\n'
                    '          <label>Localização da cooperativa\n'
                    '            <input name="card_localizacao" value="{{ card.card_localizacao }}" placeholder="Ex: '
                    'Natal/RN">\n'
                    '          </label>\n'
                    '\n'
                    '          <label>Link da localização no Google Maps\n'
                    '            <input name="card_mapa_link" value="{{ card.card_mapa_link }}" placeholder="Cole aqui '
