                    '            </label>\n'
                    '\n'
                    '            <label>Cor dos textos\n'
                    '              <input type="color" name="card_cor_texto" value="{{ card.card_cor_texto or '
                    '\'#FFFFFF\' }}">\n'
                    '            </label>\n'
                    '\n'
                    '            <label>Cor dos botões\n'
                    '              <input type="color" name="card_cor_botao" value="{{ card.card_cor_botao or '
                    '\'#FFFFFF\' }}">\n'
                    '            </label>\n'
                    '\n'
                    '            <label>Texto do botão\n'
                    '              <input type="color" name="card_cor_texto_botao" value="{{ card.card_cor_texto_botao '
                    'or \'#0047B8\' }}">\n'
                    '            </label>\n'
                    '          </div>\n'
                    '\n'
                    '          <label>Estilo visual\n'
                    '            <select name="card_estilo">\n'
                    '              <option value="ondas" {% if card.card_estilo == \'ondas\' %}selected{% endif '
                    '%}>Ondas moderno</option>\n'
                    '              <option value="limpo" {% if card.card_estilo == \'limpo\' %}selected{% endif '
                    '%}>Limpo institucional</option>\n'
                    '              <option value="vidro" {% if card.card_estilo == \'vidro\' %}selected{% endif '
                    '%}>Vidro / glass</option>\n'
                    '            </select>\n'
                    '          </label>\n'
                    '\n'
                    '          <div class="admin-subtitle">Imagens, logo e vídeo</div>\n'
                    '\n'
                    '          <label>Foto principal/perfil\n'
                    '            <input type="file" name="card_foto" accept="image/*">\n'
