                    '    </section>\n'
                    '\n'
                    '    <section class="admin-box">\n'
                    '      <h2>Cadastrar novo botão/link</h2>\n'
                    '\n'
                    '      <form method="post" enctype="multipart/form-data" action="{{ url_for(\'card_link_novo\') '
                    '}}" class="link-form">\n'
                    '        <label>Título\n'
                    '          <input name="titulo" placeholder="Ex: WhatsApp" required>\n'
                    '        </label>\n'
                    '\n'
                    '        <label>Subtítulo\n'
                    '          <input name="subtitulo" placeholder="Ex: Atendimento COOPEX">\n'
                    '        </label>\n'
                    '\n'
                    '        <label>Link/URL\n'
                    '          <input name="url" placeholder="https://wa.me/5584981110706">\n'
                    '        </label>\n'
                    '\n'
                    '        <label>Ordem\n'
                    '          <input name="ordem" type="number" value="0">\n'
                    '        </label>\n'
                    '\n'
                    '        <label class="check">\n'
                    '          <input type="checkbox" name="ativo" checked>\n'
                    '          Ativo\n'
                    '        </label>\n'
                    '\n'
                    '        <label class="full">Ícone ou logo do botão\n'
                    '          <input name="icone" type="file" accept="image/*">\n'
                    '        </label>\n'
                    '\n'
                    '        <div class="full">\n'
                    '          <button class="btn primary" type="submit">Cadastrar botão</button>\n'
                    '        </div>\n'
                    '      </form>\n'
                    '    </section>\n'
                    '\n'
                    '    <section class="admin-box">\n'
                    '      <h2>Botões/links cadastrados</h2>\n'
                    '\n'
                    "      {% for l in links|sort(attribute='ordem') %}\n"
                    '        <div class="link-card">\n'
                    '          <div class="thumb">\n'
                    '            {% if l.icone %}\n'
                    '              <img src="{{ arquivo_url(l.icone) }}" alt="{{ l.titulo }}">\n'
                    '            {% else %}\n'
                    '              ↗\n'
                    '            {% endif %}\n'
                    '          </div>\n'
                    '\n'
                    '          <form method="post" enctype="multipart/form-data" action="{{ '
                    'url_for(\'card_link_editar\', link_id=l.id) }}" class="link-form">\n'
                    '            <label>Título\n'
                    '              <input name="titulo" value="{{ l.titulo }}">\n'
                    '            </label>\n'
                    '\n'
                    '            <label>Subtítulo\n'
                    '              <input name="subtitulo" value="{{ l.subtitulo or \'\' }}">\n'
                    '            </label>\n'
                    '\n'
                    '            <label>Link\n'
                    '              <input name="url" value="{{ l.url }}">\n'
                    '            </label>\n'
                    '\n'
                    '            <label>Ordem\n'
                    '              <input name="ordem" type="number" value="{{ l.ordem }}">\n'
                    '            </label>\n'
                    '\n'
                    '            <label class="check">\n'
                    '              <input type="checkbox" name="ativo" {% if l.ativo %}checked{% endif %}>\n'
                    '              Ativo\n'
                    '            </label>\n'
                    '\n'
                    '            <label class="full">Trocar ícone/logo\n'
                    '              <input name="icone" type="file" accept="image/*">\n'
                    '              <span class="help">Cliques: {{ l.cliques or 0 }}</span>\n'
                    '            </label>\n'
                    '\n'
                    '            <div class="full">\n'
                    '              <button class="btn secondary small" type="submit">Salvar este botão</button>\n'
                    '            </div>\n'
                    '          </form>\n'
                    '\n'
                    '          <form method="post" action="{{ url_for(\'card_link_excluir\', link_id=l.id) }}" '
                    'onsubmit="return confirm(\'Excluir este botão do card?\')">\n'
                    '            <button class="btn danger small" type="submit">Excluir</button>\n'
                    '          </form>\n'
                    '        </div>\n'
                    '      {% else %}\n'
                    '        <p class="help">Nenhum botão cadastrado ainda.</p>\n'
                    '      {% endfor %}\n'
                    '    </section>\n'
                    '  </main>\n'
                    '</body>\n'
