               '      gap:14px;\n'
               '      width:min(100%,560px);\n'
               '      padding:14px 16px;\n'
               '      border-radius:22px;\n'
               '      background:rgba(255,255,255,.86);\n'
               '      border:1px solid rgba(0,71,184,.14);\n'
               '      box-shadow:0 16px 32px rgba(3,37,92,.12);\n'
               '      backdrop-filter:blur(7px);\n'
