               '      display:block;\n'
               '      color:#003c9e;\n'
               '      font-size:18px;\n'
               '      line-height:1.1;\n'
               '      font-weight:900;\n'
               '      text-transform:uppercase;\n'
               '      letter-spacing:.4px;\n'
               '      margin-bottom:5px;\n'
               '    }\n'
               '\n'
               '    .selo-utilidade-box p{\n'
